import React, { useState } from "react";
import { Link, useNavigate } from "react-router-dom";

import api from "../services/api";
import { formatErrorMessage } from "../utils/errorMessages";

const Register = () => {
  const navigate = useNavigate();
  const [formData, setFormData] = useState({ username: "", password: "" });
  const [message, setMessage] = useState("");
  const [error, setError] = useState("");
  const [loading, setLoading] = useState(false);

  const handleChange = (event) => {
    const { name, value } = event.target;
    setFormData((prev) => ({ ...prev, [name]: value }));
  };

  const handleSubmit = async (event) => {
    event.preventDefault();
    setMessage("");
    setError("");
    setLoading(true);

    try {
      await api.post("/auth/register", formData);
      setMessage("Registration successful. Redirecting to login...");
      setTimeout(() => navigate("/login"), 1000);
    } catch (err) {
      setError(formatErrorMessage(err.response?.data?.detail, "Registration failed"));
    } finally {
      setLoading(false);
    }
  };

  return (
    <div className="auth-shell">
      <div className="auth-hero accent">
        <p className="eyebrow">Edumarshal Style UI</p>
        <h1>Create your booking account and start managing campus resources.</h1>
        <p>
          Access real-time availability, place booking requests, and track
          approvals from a responsive dashboard.
        </p>
      </div>

      <div className="auth-card">
        <h2>Register</h2>
        <p>Create a client account to request bookings.</p>

        <form onSubmit={handleSubmit} className="auth-form">
          <label>
            <span>Username</span>
            <input
              type="text"
              name="username"
              value={formData.username}
              onChange={handleChange}
              required
            />
          </label>

          <label>
            <span>Password</span>
            <input
              type="password"
              name="password"
              value={formData.password}
              onChange={handleChange}
              required
            />
          </label>

          {message ? <div className="alert success">{message}</div> : null}
          {error ? <div className="alert error">{String(error)}</div> : null}

          <button type="submit" className="primary-button auth-button" disabled={loading}>
            {loading ? "Creating..." : "Register"}
          </button>
        </form>

        <p className="auth-link">
          Already registered? <Link to="/login">Back to login</Link>
        </p>
      </div>
    </div>
  );
};

export default Register;
